document.addEventListener('DOMContentLoaded', () => { const orderForm = document.getElementById('orderForm'); document.querySelectorAll('a[href^="#"]').forEach(anchor => { anchor.addEventListener('click', function (e) { e.preventDefault(); document.querySelector(this.getAttribute('href')).scrollIntoView({ behavior: 'smooth' }); }); }); if (orderForm) { orderForm.addEventListener('submit', (e) => { e.preventDefault(); const formData = new FormData(orderForm); const data = {}; formData.forEach((value, key) => { data[key] = value; }); console.log('Order Submission Received:', data); const submitBtn = orderForm.querySelector('.submit-button'); const originalText = submitBtn.textContent; submitBtn.textContent = 'FIRE! SUBMITTED...'; submitBtn.style.backgroundColor = '#00ff66'; submitBtn.style.color = '#000'; submitBtn.disabled = true; submitBtn.style.animation = 'none'; setTimeout(() => { submitBtn.style.animation = 'pulse 0.5s ease-in-out'; }, 10); setTimeout(() => { orderForm.reset(); submitBtn.textContent = originalText; submitBtn.style.backgroundColor = ''; submitBtn.style.color = ''; submitBtn.disabled = false; alert('Fire! We received your request. We will reach out to your email soon.'); }, 2500); }); }}); const style = document.createElement('style');style.textContent = ` @keyframes pulse { 0% { transform: scale(1); } 50% { transform: scale(1.05); } 100% { transform: scale(1); } }`;document.head.appendChild(style);